public class AirPlatBotMergeDeco : AirMergeWallDeco
{
	public AirPlatBotMergeDeco()
	{
		spawnChance = 1f;
		minDupeDistance = 0f;
		gridDecoGroups.Add("AirMergeDeco", decoTemplate.Factory(new int[1, 1] { { 705 } }));
		CompositeTileGridTest compositeTileGridTest = new CompositeTileGridTest();
		compositeTileGridTest.Add(new AdjTileTest(AdjTileTest.BotWallOverlayNorth)
		{
			ordOffset = new OrdinalMagnitude(3)
		});
		compositeTileGridTest.Add(new AdjTileTest(AdjTileTest.BotRightCornerOverlayNorth)
		{
			ordOffset = new OrdinalMagnitude(3)
		});
		compositeTileGridTest.Add(new AdjTileTest(AdjTileTest.BotLeftCornerOverlayNorth)
		{
			ordOffset = new OrdinalMagnitude(3)
		});
		placementTests.Add(compositeTileGridTest);
	}
}
