			if (curGridDecoGroup.Count == 0)
			{
				curGridDecoGroup = null;
				return false;
			}
			curHeight = curGridDecoGroup[0].RowCount;
			curWidth = curGridDecoGroup[0].ColCount;
			return true;
		}
		if (randomList == null)
		{
			randomList = new List<Type>();
		}
		if (!randomList.Contains(GetType()))
		{
			randomList.Add(GetType());
		}
		Debug.Log(string.Concat("WARNING:  Full random dimension decoration (", this, ")"));
		return false;
	}

	public virtual bool CanPlace(TileGrid tileGrid, int rowOrigin, int colOrigin, Transform parentTrans = null, Room room = null)
	{
		if (tileGrid == null || rowOrigin < 0 || colOrigin < 0 || tileGrid[rowOrigin, colOrigin] == null)
		{
			return false;
		}
		if (maxSpawns > 0 && spawnOrigins.Count >= maxSpawns)
		{
			return false;
		}
		InitDimensions();
		if (dimensions.MinRows == dimensions.MaxRows && dimensions.MinCols == dimensions.MaxCols)
		{
			return CanPlaceNonVariable(tileGrid, rowOrigin, colOrigin, parentTrans, room);
		}
		return CanPlaceVariable(tileGrid, rowOrigin, colOrigin, parentTrans, room);
	}

	public bool CanPlaceVariable(TileGrid tileGrid, int rowOrigin, int colOrigin, Transform parentTrans = null, Room room = null)
	{
		InvalidPositions.Clear();
		curGridDecoGroup = null;
		List<GridDimensions> list = new List<GridDimensions>();
		GridDimensions gridDimensions = null;
		IntVec2 intVec = new IntVec2(0, 0);
		for (int i = 0; i < gridDecoGroups.availableDimensions.Length; i++)
		{
			intVec = gridDecoGroups.availableDimensions[i];
			gridDimensions = new GridDimensions(intVec.x, intVec.x, intVec.y, intVec.y);
			if (RunPlacementTests(gridDimensions, tileGrid, rowOrigin, colOrigin, parentTrans, room))
			{
				list.Add(gridDimensions);
			}
		}
		if (list.Count == 0)
		{
			return false;
		}
		GridDimensions randomValue = list.GetRandomValue();
		curWidth = randomValue.MaxCols;
		curHeight = randomValue.MaxRows;
		intVec = new IntVec2(curHeight, curWidth);
		curGridDecoGroup = gridDecoGroups.dimensionToGridGroups[intVec].GetRandomValue();
		return true;
	}

	public bool RunPlacementTests(GridDimensions testDimensions, TileGrid tileGrid, int rowOrigin, int colOrigin, Transform parentTrans = null, Room room = null)
	{
		for (int i = 0; i < testDimensions.MaxRows; i++)
		{
			for (int j = 0; j < testDimensions.MaxCols; j++)
			{
				IntVec2 directionalRowCol = Globals.GetDirectionalRowCol(rowOrigin, colOrigin, direction, i, j);
				int x = directionalRowCol.x;
				int y = directionalRowCol.y;
				if (!IsDistanceValid(x, y))
				{
					return false;
				}
				if (globalSpawnGroup != string.Empty && !IsGlobalDistanceValid(GetGlobalPos(tileGrid, x, y, parentTrans, room)))
				{
					return false;
				}
				for (int k = 0; k < placementTests.Count; k++)
				{
					if (!placementTests[k].Test(tileGrid, x, y, i, j, testDimensions.MaxRows, testDimensions.MaxCols))
					{
						return false;
					}
				}
			}
		}
		return true;
	}

	public bool CanPlaceNonVariable(TileGrid tileGrid, int rowOrigin, int colOrigin, Transform parentTrans = null, Room room = null)
	{
		curGridDecoGroup = null;
		if (!RunPlacementTests(dimensions, tileGrid, rowOrigin, colOrigin, parentTrans, room))
		{
			return false;
		}
		curWidth = 0;
		curHeight = 0;
		curGridDecoGroup = null;
		if (gridDecoGroups.groups.Count > 0)
		{
			curGridDecoGroup = gridDecoGroups.groups.Values.ToArray().GetRandomValue();
			curHeight = curGridDecoGroup[0].RowCount;
			curWidth = curGridDecoGroup[0].ColCount;
		}
		else
		{
			curWidth = dimensions.MaxCols;
			curHeight = dimensions.MaxRows;
		}
		if (curWidth == 0 || curHeight == 0)
		{
			Debug.Log(string.Concat(this, ": Invalid dimensions for non-var deco"));
		}
		return true;
	}

	public virtual bool Roll()
	{
		if (spawnChance >= 1f)
		{
			return true;
		}
		return UnityEngine.Random.value <= spawnChance;
	}

	public Vector2 GetGlobalPos(TileGrid tileGrid, int row, int col, Transform parentTrans, Room room)
	{
		if (globalSpawnGroup == string.Empty || (parentTrans == null && room == null))
		{
			return Vector2.zero;
		}
		Vector2 vector = new Vector2(col, -row);
		if (room != null && parentTrans != null)
		{
			return vector + room.GetWorldOrigin(tileGrid);
		}
		return vector + new Vector2(parentTrans.transform.position.x, parentTrans.transform.position.y);
	}

	public void RecordGlobalPosition(TileGrid tileGrid, int row, int col, Transform parentTrans, Room room, bool isOrigin = false)
	{
		if (globalSpawnGroup == string.Empty || (parentTrans == null && room == null))
		{
			return;
		}
		Vector2 globalPos = GetGlobalPos(tileGrid, row, col, parentTrans, room);
		if (isOrigin)
		{
			if (!GlobalSpawnOrigins.ContainsKey(globalSpawnGroup))
			{
				GlobalSpawnOrigins[globalSpawnGroup] = new List<Vector2>();
			}

			}
			GlobalSpawnOrigins[globalSpawnGroup].Add(globalPos);
		}
		else
		{
			if (!GlobalSpawnPositions.ContainsKey(globalSpawnGroup))
			{
				GlobalSpawnPositions[globalSpawnGroup] = new List<Vector2>();
			}
			GlobalSpawnPositions[globalSpawnGroup].Add(globalPos);
		}
	}

	public static void ClearGlobalPositions()
	{
		GlobalSpawnPositions.Clear();
		GlobalSpawnOrigins.Clear();
	}

	public virtual void Place(TileGrid tileGrid, int rowOrigin, int colOrigin, Transform parentTrans = null, Room room = null)
	{
		if (tileGrid == null || rowOrigin < 0 || colOrigin < 0 || tileGrid[rowOrigin, colOrigin] == null || curWidth == 0 || curHeight == 0)
		{
			return;
		}
		spawnOrigins.Add(new IntVec2(rowOrigin, colOrigin));
		RecordGlobalPosition(tileGrid, rowOrigin, colOrigin, parentTrans, room, isOrigin: true);
		for (int i = 0; i < RowCount; i++)
		{
			for (int j = 0; j < ColCount; j++)
			{
				IntVec2 directionalRowCol = Globals.GetDirectionalRowCol(rowOrigin, colOrigin, direction, i, j);
				int x = directionalRowCol.x;
				int y = directionalRowCol.y;
				spawnPositions.Add(new IntVec2(x, y));
				RecordGlobalPosition(tileGrid, x, y, parentTrans, room);
				if (curGridDecoGroup != null)
				{
					for (int k = 0; k < curGridDecoGroup.Count; k++)
					{
						if (tileGrid.InBounds(x, y))
						{
							curGridDecoGroup[k].Apply(tileGrid, x, y, i, j, direction, prefabRowOffset, prefabColOffset);
						}
					}
				}
				int colOffset = j;
				int rowOffset = i;
				for (int l = 0; l < autoTilers.Count; l++)
				{
					autoTilers[l].Apply(tileGrid, x, y, rowOffset, colOffset, RowCount, ColCount);
				}
				if (spawnPrefab)
				{
					SpawnPrefab(tileGrid, x, y, i, j, parentTrans, room);
				}
			}
		}
	}

	public virtual GameObject SpawnPrefab(TileGrid tileGrid, int rowOrigin, int colOrigin, int rowOffset = 0, int colOffset = 0, Transform parentTrans = null, Room room = null)
	{
		if (!spawnPrefabOnEveryTile && (rowOffset != 0 || colOffset != 0))
		{
			return null;
		}
		Vector2 vector = new Vector2((float)colOrigin + prefabWorldOffsetX, (float)(-rowOrigin) + (0f - prefabWorldOffsetY));
		if (room != null && parentTrans != null)
		{
			vector += room.GetWorldOrigin(tileGrid);
		}
		GameObject gameObject = UnityEngine.Object.Instantiate(prefab, new Vector3(vector.x, vector.y, 0f), Quaternion.identity);
		gameObject.name += Globals.generatedPostfix;
		if (parentTrans != null)
		{
			gameObject.transform.SetParent(parentTrans);
		}
		SpawnAuxDecos(tileGrid, rowOrigin, colOrigin, rowOffset, colOffset, parentTrans, room);
		return gameObject;
	}

	public virtual void InitAuxDecos()
	{
	}

	public void SpawnAuxDecos(TileGrid tileGrid, int rowOrigin, int colOrigin, int rowOffset = 0, int colOffset = 0, Transform parentTrans = null, Room room = null)
	{
		if (AuxDecos == null || AuxDecos.Length == 0)
		{
			return;
		}
		if (shuffleAuxDecos)
		{
			auxDecos.Shuffle();
		}
		for (int i = 0; i < AuxDecos.Length; i++)
		{
			AuxDeco auxDeco = AuxDecos[i];
			if (auxDeco.deco != null)
			{
				auxDeco.deco.spawnPositions.Clear();
				auxDeco.deco.spawnOrigins.Clear();
				int rowOrigin2 = rowOrigin + auxDeco.rowOffset;
				int colOrigin2 = colOrigin + auxDeco.colOffset;
				if (auxDeco.deco.CanPlace(tileGrid, rowOrigin2, colOrigin2, parentTrans, room))
				{
					auxDeco.deco.Place(tileGrid, rowOrigin2, colOrigin2, parentTrans, room);
				}
			}
			else
			{
				GameObject gameObject = prefab;
				float num = prefabWorldOffsetX;
				float num2 = prefabWorldOffsetY;
				SpawnPrefab(tileGrid, rowOrigin, colOrigin, 0, 0, parentTrans, room);
				prefab = gameObject;
				prefabWorldOffsetX = num;
				prefabWorldOffsetY = num2;
			}
		}
	}
