	public void Apply(Transform newWorldTransform = null, TileGrid newWorldTileGrid = null, Room room = null)
	{
		if (decorationToApply == string.Empty)
		{
			return;
		}
		try
		{
			decoration = Decorations[decorationToApply];
		}
		catch (Exception)
		{
			Debug.Log("Failed to find decoration to apply: " + decorationToApply);
		}
		InitWorldInfo(newWorldTransform, newWorldTileGrid);
		if (worldTileGrid != null && worldTileGrid.InBounds(row, col))
		{
			decoration.spawnPositions.Clear();
			decoration.spawnOrigins.Clear();
			if (!decoration.CanPlace(worldTileGrid, row, col))
			{
			}
			decoration.spawnPrefab = false;
			decoration.Place(worldTileGrid, row, col, newWorldTransform, room);
		}
	}

	public void InitWorldInfo(Transform newWorldTransform = null, TileGrid newWorldTileGrid = null)
	{
		worldTransform = newWorldTransform;
		worldTileGrid = newWorldTileGrid;
		Room room = null;
		if (worldTransform == null)
		{
			if (Level.levelContainer != null)
			{
				worldTransform = Level.levelContainer.transform;
			}
			else
			{
				GameObject[] array = GameObject.FindGameObjectsWithTag("Room");
				if (array.Length > 0)
				{
					worldTransform = array[0].transform;
					room = array[0].GetComponent<Room>();
					for (int i = 0; i < array.Length; i++)
					{
						if (array[i].gameObject.activeSelf)
						{
							worldTransform = array[i].transform;
							room = array[i].GetComponent<Room>();
							break;
						}
					}
				}
			}
		}
		if (worldTileGrid == null)
		{
			if (Level.tileGrid != null)
			{
				worldTileGrid = Level.tileGrid;
			}
			else if (room != null)
			{
				worldTileGrid = room.tileGrid;
			}
		}
		if (worldTransform == null || worldTileGrid == null)
		{
			row = -1;
			col = -1;
		}
		else
		{
			SetRowColPosition();
		}
	}

	public void SetRowColPosition()
	{
		if (!(worldTransform == null))
		{
			int num = (int)Mathf.Ceil(worldTransform.position.y - transform.position.y - decoration.prefabWorldOffsetY - (float)decorationOffsetY);
			int num2 = -(int)Mathf.Ceil(worldTransform.position.x - transform.position.x + decoration.prefabWorldOffsetX + (float)decorationOffsetX);
			if (row < 0 || col < 0 || num != row || num2 != col)
			{
				row = num;
				col = num2;
			}
		}
	}

	public static void ApplyAllDecorations(Transform parentTrans = null, TileGrid tileGrid = null, Room room = null)
	{
		DecorationApplier[] componentsInChildren = parentTrans.GetComponentsInChildren<DecorationApplier>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			if (!componentsInChildren[i].gameObject.name.Contains(Globals.generatedPostfix))
			{
				componentsInChildren[i].Apply(parentTrans, tileGrid, room);
			}
		}
	}
