using System.Collections.Generic;
using System.Linq;

public class GridTestGroup<TGrid, TType> where TGrid : IGrid<TType>
{
	private List<GridTest<TGrid, TType>> tests;

	public GridTestGroup()
	{
		tests = new List<GridTest<TGrid, TType>>();
	}

	public virtual bool Test(TGrid grid, int row, int col, int rowOffset = 0, int colOffset = 0, int rowCount = 0, int colCount = 0)
	{
		if (tests == null || tests.Count == 0)
		{
			return true;
		}
		for (int i = 0; i < tests.Count; i++)
		{
			if (!tests[i].Test(grid, row, col, rowOffset, colOffset, rowCount, colCount))
			{
				return false;
			}
		}
		return true;
	}

	public void Add(GridTest<TGrid, TType> newTest)
	{
		tests.Add(newTest);
		tests = tests.OrderBy((GridTest<TGrid, TType> x) => x.priority).ToList();
	}
}
